mapper.select:
SELECT
aa.*
FROM
`ap_article` aa
LEFT JOIN ap_article_config aac ON aa.id = aac.article_id

    and aac.is_delete != 1
    and aac.is_down != 1

        and aa.publish_time < #{dto.minBehotTime}


        and aa.publish_time > #{dto.maxBehotTime}


        and aa.channel_id = #{dto.tag}


        and JSON_CONTAINS(aa.tags, JSON_QUOTE(#{dto.tagName}))


ORDER BY aa.publish_time DESC, (COALESCE(aa.views, 0) + COALESCE(aa.likes, 0) * 2 + COALESCE(aa.comment, 0) * 3) DESC, aa.id DESC
limit #{dto.size}

SELECT aa.* FROM `ap_article` aa INNER JOIN ap_article_config aac ON aa.id = aac.article_id
and aac.is_delete != 1 and aac.is_down != 1 and aac.is_recommend = 1 and aa.status = 9
and aa.publish_time >= DATE_SUB(NOW(), INTERVAL #{windowDays} DAY)
and aa.channel_id = #{channelId}
and JSON_CONTAINS(aa.tags, JSON_QUOTE(#{tagName}))
ORDER BY COALESCE(aa.score, 0) DESC, aa.publish_time DESC, aa.id DESC LIMIT #{maxCandidates}

SELECT aa.* FROM `ap_article` aa INNER JOIN ap_article_config aac ON aa.id = aac.article_id
and aac.is_delete != 1 and aac.is_down != 1 and aac.is_recommend = 1 and aa.status = 9
and aa.publish_time >= DATE_SUB(NOW(), INTERVAL #{windowDays} DAY)
and aa.author_id IN
#{aid}
ORDER BY COALESCE(aa.score, 0) DESC, aa.publish_time DESC, aa.id DESC LIMIT #{maxCandidates}

SELECT aa.* FROM `ap_article` aa INNER JOIN ap_article_config aac ON aa.id = aac.article_id
and aac.is_delete != 1 and aac.is_down != 1 and aa.status = 9
and aa.channel_id = #{channelId}
and JSON_CONTAINS(aa.tags, JSON_QUOTE(#{tagName}))
and aa.author_id IN
#{aid}
ORDER BY aa.publish_time DESC, aa.id DESC LIMIT #{offset}, #{limit}

